`timescale 1ns / 1ps
/*
 * rn_top.v — RadarNet-1D accelerator, v2
 * =======================================
 * A single W×W PE array is time-multiplexed over all convolution layers by a
 * descriptor-driven sequencer (layer_table.vh, generated by int_quant.py).
 * Loop nest per layer, one W×W MAC step issued every clock:
 *
 *   for og < NOG:  for t < LOUT:  for ig < NIG:  for k < K:
 *       acc[og*W + o] += Σ_i  W[og*W+o][ig*W+i][k] * X[ig*W+i][t*S + k - P]
 *
 * Datapath (fully pipelined, no bubbles between output groups):
 *   A  issue: counters → position        A2 buffer/ROM addresses
 *   B  BRAM read (2-cycle, output reg)
 *   C  operand register + zero padding   PE multiply + log2(W) adder tree
 *   E  accumulate                        R0..R5 per-lane integer requant:
 *        y = sat8(relu?(((acc + b) * M + (skip * Ms << SK) + 2^(SH-1)) >>> SH))
 *
 * Three ping-pong feature buffers hold every activation on chip; the input
 * frame is written into buffer 2. FC logits are taken as raw (acc + b).
 */
module rn_top #(
    parameter W            = 8,
    parameter NUM_CLASSES  = 4,                // must match the exported layer table
    parameter PE_DSP       = (W * W <= 128),   // DSP48 multipliers if they fit
    parameter WEIGHTS_FILE = "weights.mem",
    parameter PARAMS_FILE  = "params.mem"
)(
    input  wire          clk,
    input  wire          rst_n,
    input  wire          start,
    input  wire          iq_valid,
    input  wire [15:0]   iq_data,          // {I[7:0], Q[7:0]}
    output reg           busy,
    output reg           done,
    output reg           result_valid,
    output reg  [((NUM_CLASSES > 2) ? $clog2(NUM_CLASSES) : 1)-1:0] class_id,
    output wire          anomaly_flag,
    output reg  [31:0]   cycle_count,      // start → result_valid, incl. load
    output reg  [32*NUM_CLASSES-1:0] logits   // int32 per class (debug / verification)
);
    localparam CW        = (NUM_CLASSES > 2) ? $clog2(NUM_CLASSES) : 1;
    localparam LV        = $clog2(W);
    localparam SUMW      = 16 + LV;
    localparam ACCW      = 24;
    localparam BUF_DEPTH = (2048 / W > 128) ? 2048 / W : 128;
    localparam AW        = $clog2(BUF_DEPTH);
    localparam PL        = 1 + LV;          // PE array latency
    localparam DRAIN     = 20 + LV;         // > issue-to-write latency
    localparam N_SAMPLES = 128;
    localparam GAP_LAYER = 6;               // GAP runs after this layer
    localparam GAP_SRC   = 2, GAP_DST = 0;

    // ── Reset: asynchronous assert, synchronous de-assert ───────────
    (* max_fanout = 32 *) reg [1:0] rst_sync;
    always @(posedge clk or negedge rst_n)
        if (!rst_n) rst_sync <= 2'b00;
        else        rst_sync <= {rst_sync[0], 1'b1};
    wire rst_ni = rst_sync[1];

    // ── Layer descriptor (combinational from `layer`) ───────────────
    reg [3:0]  layer;
    reg [7:0]  d_nig, d_nog, d_lin, d_lout, d_k, d_s, d_p;
    reg        d_relu, d_res, d_raw;
    reg [1:0]  d_src, d_dst, d_skp;
    reg [15:0] d_wb, d_pb, d_ms;
    reg [5:0]  d_sh;
    reg [4:0]  d_sk;
`define RN_LAYER_TABLE
    `include "layer_table.vh"
`undef RN_LAYER_TABLE

    // Registered copy of the descriptor: constant for a whole layer, so the
    // one-cycle lag (absorbed by S_INIT) takes the table decode off every path.
    reg [7:0]  q_nig, q_nog, q_lin, q_lout, q_k, q_s, q_p;
    reg        q_relu, q_res, q_raw;
    reg [1:0]  q_src, q_dst, q_skp;
    reg [15:0] q_wb, q_pb, q_ms;
    reg [5:0]  q_sh;
    reg [4:0]  q_sk;
    reg [23:0] q_msk;                          // Ms << SK, one DSP operand
    reg [7:0]  q_km1, q_nigm1, q_loutm1, q_nogm1;   // loop bounds - 1
    always @(posedge clk) begin
        q_msk <= d_ms << d_sk;
        q_km1 <= d_k - 1; q_nigm1 <= d_nig - 1; q_loutm1 <= d_lout - 1; q_nogm1 <= d_nog - 1;
        q_nig <= d_nig; q_nog <= d_nog; q_lin <= d_lin; q_lout <= d_lout;
        q_k <= d_k; q_s <= d_s; q_p <= d_p;
        q_relu <= d_relu; q_res <= d_res; q_raw <= d_raw;
        q_src <= d_src; q_dst <= d_dst; q_skp <= d_skp;
        q_wb <= d_wb; q_pb <= d_pb; q_ms <= d_ms; q_sh <= d_sh; q_sk <= d_sk;
    end

    generate if (EXPORT_LANES != W) begin : lanes_mismatch
        ERROR_layer_table_exported_for_different_W u_err();
    end endgenerate
    generate if (EXPORT_CLASSES != NUM_CLASSES) begin : classes_mismatch
        ERROR_layer_table_exported_for_different_NUM_CLASSES u_err();
    end endgenerate

    // ── Weight / parameter ROMs ─────────────────────────────────────
    (* rom_style = "block" *)
    reg [8*W*W-1:0] wrom [0:W_DEPTH-1];
    reg [48*W-1:0]  prom [0:P_DEPTH-1];
    initial begin
        $readmemh(WEIGHTS_FILE, wrom);
        $readmemh(PARAMS_FILE,  prom);
    end
    reg  [15:0]      a_waddr, a2_waddr;
    reg  [8*W*W-1:0] w_q, w_q2;
    reg  [48*W-1:0]  p_q;
    wire [15:0]      p_addr;
    always @(posedge clk) begin
        w_q  <= wrom[a2_waddr];
        w_q2 <= w_q;                 // output register, matches rn_buf latency
        p_q <= prom[p_addr];
    end

    // ── Feature buffers ─────────────────────────────────────────────
    reg  [AW-1:0]  b_raddr [0:2];
    wire [8*W-1:0] b_rdata [0:2];
    reg            b_we    [0:2];
    reg  [AW-1:0]  b_waddr [0:2];
    reg  [8*W-1:0] b_wdata [0:2];
    genvar gb;
    generate for (gb = 0; gb < 3; gb = gb + 1) begin : fbuf
        rn_buf #(.W(W), .DEPTH(BUF_DEPTH)) u_buf (
            .clk(clk), .we(b_we[gb]), .waddr(b_waddr[gb]), .wdata(b_wdata[gb]),
            .raddr(b_raddr[gb]), .rdata(b_rdata[gb]));
    end endgenerate

    // ── Main FSM ────────────────────────────────────────────────────
    localparam S_IDLE=0, S_LOAD=1, S_INIT=2, S_ISSUE=3, S_DRAIN=4, S_GAP=5,
               S_AMAX1=6, S_AMAX2=7;
    reg [2:0]  state;
    reg [7:0]  ld_cnt;
    reg [7:0]  drain_cnt;
    reg        gap_start;
    wire       gap_done;

    // Issue counters
    reg [7:0]  og, t, ig, k;
    reg [15:0] w_base_og, w_off, rowlen;
    reg [AW-1:0] src_base, dst_base;
    reg signed [9:0] tsp;           // t*S - P, updated incrementally
    wire signed [9:0] pos = tsp + $signed({2'b0, k});
    wire       oob = (pos < 0) || (pos >= $signed({2'b0, q_lin}));

    // Pipeline control: A (issue) → B (BRAM) → C (operands) → PE → E (acc)
    reg            a_v, a_first, a_last, a_oob;
    reg [AW-1:0]   a_base, a_pos, a_dst;
    reg [7:0]      a_og;
    reg            a2_v, a2_first, a2_last, a2_oob;
    reg [AW-1:0]   a2_src, a2_dst;
    reg [7:0]      a2_og;
    reg            b_v, b_first, b_last, b_oob;
    reg [AW-1:0]   b2_dst;
    reg [7:0]      b2_og;
    reg            b2_v, b2_first, b2_last, b2_oob;
    reg [AW-1:0]   b_dst;
    reg [7:0]      b_og;
    reg            c_v, c_first, c_last;
    reg [AW-1:0]   c_dst;
    reg [7:0]      c_og;
    reg [8*W-1:0]  c_x;
    reg [8*W*W-1:0] c_w;
    // Control delay matching the PE array latency
    reg            pe_v   [0:PL-1];
    reg            pe_fst [0:PL-1];
    reg            pe_lst [0:PL-1];
    reg [AW-1:0]   pe_dst [0:PL-1];
    reg [7:0]      pe_og  [0:PL-1];
    wire           e_v   = pe_v[PL-1];
    wire           e_fst = pe_fst[PL-1];
    wire           e_lst = pe_lst[PL-1];
    wire [AW-1:0]  e_dst = pe_dst[PL-1];
    wire [7:0]     e_og  = pe_og[PL-1];

    wire [SUMW*W-1:0] pe_sum;
    rn_pe_array #(.W(W), .USE_DSP(PE_DSP)) u_pe (.clk(clk), .x_word(c_x), .w_row(c_w), .sum_out(pe_sum));

    // Skip and per-channel params are fetched so they arrive with the final acc
    assign p_addr = q_pb + e_og;
    wire [AW-1:0]  skip_raddr = e_dst;
    wire [8*W-1:0] src_rdata  = b_rdata[q_src];
    wire [8*W-1:0] skip_rdata = b_rdata[q_skp];

    // ── Accumulate (E) and requant (R0..R5) ─────────────────────────
    reg signed [ACCW-1:0] acc [0:W-1];
    reg            f_v;
    reg [AW-1:0]   f_dst;
    reg [7:0]      f_og;
    reg            r0_v, r1_v, r2_v, r3_v;
    reg [AW-1:0]   r0_dst, r1_dst, r2_dst, r3_dst;
    reg signed [ACCW-1:0] r0_acc [0:W-1];
    reg [48*W-1:0] r0_p;
    reg signed [ACCW:0]   r1_t  [0:W-1];
    reg        [15:0]     r1_m  [0:W-1];
    reg signed [7:0]      r1_skw [0:W-1];
    reg signed [47:0]     r2_m  [0:W-1];
    reg signed [47:0]     r2_sk [0:W-1];
    reg signed [47:0]     r3_v_ [0:W-1];
    reg            r4_v;
    reg [AW-1:0]   r4_dst;
    reg signed [47:0]     r4_y  [0:W-1];
    reg            eng_we;
    reg [AW-1:0]   eng_waddr;
    reg [8*W-1:0]  eng_wdata;

    function [7:0] sat8;
        input signed [47:0] v;
        sat8 = (v > 127) ? 8'sd127 : (v < -128) ? -8'sd128 : v[7:0];
    endfunction

    integer o, i;
    reg signed [ACCW-1:0] acc_nxt;
    reg signed [47:0]     y;
    wire signed [47:0]    rnd = 48'sd1 <<< (q_sh - 1);

    always @(posedge clk) begin
        // E: accumulate
        f_v   <= e_v & e_lst;
        f_dst <= e_dst;
        f_og  <= e_og;
        for (o = 0; o < W; o = o + 1) begin
            if (e_v) begin
                acc_nxt = (e_fst ? 0 : acc[o]) + $signed(pe_sum[SUMW*o +: SUMW]);
                acc[o] <= acc_nxt;
            end
        end
        // R0: register final acc, per-channel params and skip word (BRAM → reg)
        r0_v    <= f_v & ~q_raw;
        r0_dst  <= f_dst;
        r0_p    <= p_q;
        for (o = 0; o < W; o = o + 1)
            r0_acc[o] <= acc[o];
        // R1: bias add, skip product (skip word arrives from the BRAM output register)
        r1_v   <= r0_v;
        r1_dst <= r0_dst;
        for (o = 0; o < W; o = o + 1) begin
            r1_t[o]  <= r0_acc[o] + $signed(r0_p[48*o +: 24]);
            r1_m[o]  <= r0_p[48*o + 32 +: 16];
            r1_skw[o] <= q_res ? skip_rdata[8*o +: 8] : 8'd0;
        end
        // R2: requant multiply, skip multiply (pre-shifted constant)
        r2_v   <= r1_v;
        r2_dst <= r1_dst;
        for (o = 0; o < W; o = o + 1) begin
            r2_m[o]  <= r1_t[o] * $signed({1'b0, r1_m[o]});
            r2_sk[o] <= r1_skw[o] * $signed({1'b0, q_msk});
        end
        // R3: sum + rounding constant
        r3_v   <= r2_v;
        r3_dst <= r2_dst;
        for (o = 0; o < W; o = o + 1)
            r3_v_[o] <= r2_m[o] + r2_sk[o] + rnd;
        // R4: arithmetic shift
        r4_v   <= r3_v;
        r4_dst <= r3_dst;
        for (o = 0; o < W; o = o + 1)
            r4_y[o] <= r3_v_[o] >>> q_sh;
        // R5: ReLU, saturate → destination buffer
        eng_we    <= r4_v;
        eng_waddr <= r4_dst;
        for (o = 0; o < W; o = o + 1) begin
            y = r4_y[o];
            if (q_relu && y < 0) y = 0;
            eng_wdata[8*o +: 8] <= sat8(y);
        end
    end

    // FC logits: raw acc + bias, class c = output group c/W, lane c%W
    integer c;
    always @(posedge clk)
        if (f_v && q_raw)
            for (c = 0; c < NUM_CLASSES; c = c + 1)
                if (f_og == c / W)
                    logits[32*c +: 32] <= acc[c % W] + $signed(p_q[48*(c % W) +: 24]);

    // ── GAP ─────────────────────────────────────────────────────────
    wire [AW-1:0]  gap_raddr, gap_waddr;
    wire [8*W-1:0] gap_wdata;
    wire           gap_we;
    rn_gap #(.W(W), .NCH(64), .T(32), .AW(AW)) u_gap (
        .clk(clk), .rst_n(rst_ni), .start(gap_start), .done(gap_done),
        .raddr(gap_raddr), .rdata(b_rdata[GAP_SRC]),
        .we(gap_we), .waddr(gap_waddr), .wdata(gap_wdata));

    // ── Buffer port muxes ───────────────────────────────────────────
    reg            ld_we;
    reg [AW-1:0]   ld_waddr;
    reg [8*W-1:0]  ld_wdata;
    always @(*) begin
        for (i = 0; i < 3; i = i + 1) begin
            if (state == S_GAP)          b_raddr[i] = gap_raddr;
            else if (i == q_src)         b_raddr[i] = a2_src;
            else                         b_raddr[i] = skip_raddr;
            if (ld_we && i == 2) begin
                b_we[i] = 1; b_waddr[i] = ld_waddr;  b_wdata[i] = ld_wdata;
            end else if (gap_we && i == GAP_DST) begin
                b_we[i] = 1; b_waddr[i] = gap_waddr; b_wdata[i] = gap_wdata;
            end else begin
                b_we[i] = eng_we && (i == q_dst);
                b_waddr[i] = eng_waddr; b_wdata[i] = eng_wdata;
            end
        end
    end

    // ── Argmax over int32 logits (first maximum wins, as numpy) ─────
    // Sequential: one 32-bit compare per cycle (NUM_CLASSES cycles) keeps it
    // off the critical path; strict '>' keeps the lower index on ties.
    reg [CW-1:0]      am_i, am_j;
    reg signed [31:0] am_v;
    wire signed [31:0] lg_j = logits[32*am_j +: 32];
    assign anomaly_flag = result_valid && (class_id != 0);

    // ── Sequencer ───────────────────────────────────────────────────
    integer p;
    always @(posedge clk or negedge rst_ni) begin
        if (!rst_ni) begin
            state <= S_IDLE; layer <= 0; busy <= 0; done <= 0; result_valid <= 0;
            class_id <= 0; cycle_count <= 0; ld_cnt <= 0; drain_cnt <= 0;
            gap_start <= 0; ld_we <= 0; ld_waddr <= 0; ld_wdata <= 0;
            og <= 0; t <= 0; ig <= 0; k <= 0; tsp <= 0;
            w_base_og <= 0; w_off <= 0; rowlen <= 0; src_base <= 0; dst_base <= 0;
            a_v <= 0; a_first <= 0; a_last <= 0; a_oob <= 0;
            a_base <= 0; a_pos <= 0; a_dst <= 0; a_og <= 0; a_waddr <= 0;
            a2_v <= 0; b_v <= 0; b2_v <= 0; c_v <= 0;
            for (p = 0; p < PL; p = p + 1) pe_v[p] <= 0;
        end else begin
            done      <= 0;
            gap_start <= 0;
            ld_we     <= 0;
            a_v       <= 0;
            if (busy) cycle_count <= cycle_count + 1;

            case (state)
            S_IDLE: if (start) begin
                busy <= 1; result_valid <= 0; cycle_count <= 0;
                ld_cnt <= 0; state <= S_LOAD;
            end

            S_LOAD: if (iq_valid) begin
                ld_we    <= 1;
                ld_waddr <= ld_cnt;
                ld_wdata <= {{(8*W-16){1'b0}}, iq_data[7:0], iq_data[15:8]}; // lane0=I, lane1=Q
                ld_cnt   <= ld_cnt + 1;
                if (ld_cnt == N_SAMPLES - 1) begin layer <= 0; state <= S_INIT; end
            end

            S_INIT: begin
                og <= 0; t <= 0; ig <= 0; k <= 0; tsp <= -$signed({2'b0, d_p});
                w_base_og <= d_wb; w_off <= 0; rowlen <= d_nig * d_k;
                src_base <= 0; dst_base <= 0;
                state <= S_ISSUE;
            end

            S_ISSUE: begin
                a_v     <= 1;
                a_base  <= src_base;
                a_pos   <= oob ? 0 : pos[AW-1:0];
                a_oob   <= oob;
                a_waddr <= w_base_og + w_off;
                a_first <= (ig == 0) && (k == 0);
                a_last  <= (ig == q_nigm1) && (k == q_km1);
                a_dst   <= dst_base + t;
                a_og    <= og;
                if (k != q_km1) begin
                    k <= k + 1; w_off <= w_off + 1;
                end else begin
                    k <= 0;
                    if (ig != q_nigm1) begin
                        ig <= ig + 1; w_off <= w_off + 1; src_base <= src_base + q_lin;
                    end else begin
                        ig <= 0; w_off <= 0; src_base <= 0;
                        if (t != q_loutm1) begin
                            t <= t + 1; tsp <= tsp + $signed({2'b0, q_s});
                        end else begin
                            t <= 0; tsp <= -$signed({2'b0, q_p});
                            if (og != q_nogm1) begin
                                og <= og + 1; w_base_og <= w_base_og + rowlen;
                                dst_base <= dst_base + q_lout;
                            end else begin
                                drain_cnt <= DRAIN; state <= S_DRAIN;
                            end
                        end
                    end
                end
            end

            S_DRAIN: begin
                if (drain_cnt != 0) drain_cnt <= drain_cnt - 1;
                else if (layer == GAP_LAYER) begin
                    gap_start <= 1; state <= S_GAP;
                end else if (layer == NUM_LAYERS - 1) begin
                    state <= S_AMAX1;
                end else begin
                    layer <= layer + 1; state <= S_INIT;
                end
            end

            S_GAP: if (gap_done) begin layer <= NUM_LAYERS - 1; state <= S_INIT; end

            S_AMAX1: begin
                am_v <= logits[31:0]; am_i <= 0; am_j <= 1;
                state <= S_AMAX2;
            end

            S_AMAX2: begin
                if (lg_j > am_v) begin am_v <= lg_j; am_i <= am_j; end
                if (am_j == NUM_CLASSES - 1) begin
                    class_id <= (lg_j > am_v) ? am_j : am_i;
                    result_valid <= 1; done <= 1; busy <= 0;
                    state <= S_IDLE;
                end else
                    am_j <= am_j + 1;
            end
            default: state <= S_IDLE;
            endcase

            // A2: address add
            a2_v <= a_v; a2_first <= a_first; a2_last <= a_last; a2_oob <= a_oob;
            a2_dst <= a_dst; a2_og <= a_og;
            a2_src <= a_base + a_pos;
            a2_waddr <= a_waddr;
            // B, B2: BRAM read + output register
            b_v <= a2_v; b_first <= a2_first; b_last <= a2_last; b_oob <= a2_oob;
            b_dst <= a2_dst; b_og <= a2_og;
            b2_v <= b_v; b2_first <= b_first; b2_last <= b_last; b2_oob <= b_oob;
            b2_dst <= b_dst; b2_og <= b_og;
            // C: operand stage (zero padding outside the frame)
            c_v <= b2_v; c_first <= b2_first; c_last <= b2_last;
            c_dst <= b2_dst; c_og <= b2_og;
            c_x <= b2_oob ? {8*W{1'b0}} : src_rdata;
            c_w <= w_q2;
            // PE-latency control delay
            pe_v[0] <= c_v; pe_fst[0] <= c_first; pe_lst[0] <= c_last;
            pe_dst[0] <= c_dst; pe_og[0] <= c_og;
            for (p = 1; p < PL; p = p + 1) begin
                pe_v[p] <= pe_v[p-1]; pe_fst[p] <= pe_fst[p-1]; pe_lst[p] <= pe_lst[p-1];
                pe_dst[p] <= pe_dst[p-1]; pe_og[p] <= pe_og[p-1];
            end
        end
    end
endmodule
